export class Addresses extends HTMLElement {
  constructor() {
    super();
  }

  static get observedAttributes() {
    return ["address"];
  }

  connectedCallback() {
    this.setPage();
  }

  private setPage() {
    const deleteButtons = this.querySelectorAll(
      "[js-delete-address]",
    ) as NodeListOf<HTMLButtonElement>;
    for (const button of deleteButtons) {
      button.addEventListener("click", () => {
        if (button.dataset.addressUrl) {
          this.handleDelete(button.dataset.addressUrl);
        }
      });
    }
  }

  private handleDelete(addressUrl: string) {
    if (!addressUrl) return;
    const form = document.createElement("form");
    form.setAttribute("method", "post");
    form.setAttribute("action", addressUrl);

    const hiddenField = document.createElement("input");
    hiddenField.setAttribute("type", "hidden");
    hiddenField.setAttribute("name", "_method");
    hiddenField.setAttribute("value", "delete");
    form.appendChild(hiddenField);

    document.body.appendChild(form);
    form.submit();
    document.body.removeChild(form);
  }
}

customElements.define("uwp-addresses", Addresses);
